def esc(s): return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def block(lang, data, upd):
    title, secs = data[lang]
    h = '<div lang="%s" data-l="%s"><h1>%s</h1><p class="upd">%s</p>' % (lang, lang, esc(title), upd)
    for t, ps in secs:
        h += '<h2>%s</h2>' % esc(t)
        for p in ps: h += '<p>%s</p>' % esc(p)
    return h + '</div>'

TPL = open('/home/claude/work2/pol_tpl.html').read()
def page(data, odata, ofile):
    en_t, es_t = data['en'][0], data['es'][0]
    es_block = block('es', data, UPD_ES).replace('<div lang="es" data-l="es">', '<div lang="es" data-l="es" hidden>')
    r = TPL
    for k, v in [('@@TITLE@@', en_t), ('@@EN@@', block('en', data, UPD_EN)), ('@@ES@@', es_block), ('@@OFILE@@', ofile), ('@@OEN@@', odata['en'][0]), ('@@OES@@', odata['es'][0]), ('@@TEN@@', en_t), ('@@TES@@', es_t)]:
        r = r.replace(k, v)
    return r
open('/home/claude/sams-rental/privacy.html','w').write(page(PRIV, TERMS, 'terms.html'))
